import math

def _rendezvous_slot_intervals(sandbox):
    return sandbox.get_rendezvous_slots()

def build_agent(sandbox):
    return sandbox.get_seeker_body()

def agent_action(sandbox, agent_body, step_count):
    if not hasattr(agent_body, '_state'):
        agent_body._state = {
            'last_tx': 0.0, 'last_ty': 0.0,
            'tvx': 0.0, 'tvy': 0.0,
            'activation_streak': 0
        }
    state = agent_body._state

    tx, ty = sandbox.get_target_position()
    sx, sy = sandbox.get_seeker_position()
    svx, svy = sandbox.get_seeker_velocity()

    # Track activation streak
    x_min, x_max = sandbox.get_corridor_bounds()
    if x_min <= sx <= x_max:
        state['activation_streak'] += 1
    else:
        state['activation_streak'] = 0

    activation_achieved = state['activation_streak'] >= 80

    # Update target velocity estimate
    if step_count % 5 == 0 and step_count > 5:
        dt = 5.0 / 60.0
        state['tvx'] = 0.5 * state['tvx'] + 0.5 * (tx - state['last_tx']) / dt
        state['tvy'] = 0.5 * state['tvy'] + 0.5 * (ty - state['last_ty']) / dt
        state['last_tx'], state['last_ty'] = tx, ty
    elif step_count <= 5:
        state['last_tx'], state['last_ty'] = tx, ty

    slots = _rendezvous_slot_intervals(sandbox)
    in_slot = any(lo <= step_count <= hi for (lo, hi) in slots)

    # Determine target position
    if step_count < 110 or not activation_achieved:
        # During activation phase or not yet activated: target is corridor midpoint
        gx = (x_min + x_max) / 2.0
        gy = 1.35
    elif in_slot:
        gx, gy = tx, ty
    else:
        # After activation but not in a rendezvous slot: track the target
        gx, gy = tx, ty

    # PD control
    if in_slot:
        fx = 150.0 * (gx - sx) + 30.0 * (state['tvx'] - svx)
        fy = 150.0 * (gy - sy) + 30.0 * (state['tvy'] - svy)
    else:
        fx = 150.0 * (gx - sx) - 30.0 * svx
        fy = 90.0 * (gy - sy) - 22.5 * svy

    # Enforce minimum thrust if needed
    if step_count >= 110 and not activation_achieved and abs(gx - sx) > 0.05:
        if abs(fx) < 110.0:
            fx = 110.0 if (gx - sx) > 0 else -110.0

    # Cap thrust to avoid cooldown
    mag = math.sqrt(fx * fx + fy * fy)
    if mag > 119.0:
        fx, fy = fx * 119.0 / mag, fy * 119.0 / mag

    sandbox.apply_seeker_force(fx, fy)
